    if m * k > len(bloomDay): return -1
    lo, hi = min(bloomDay), max(bloomDay)
    ans = hi
    while lo <= hi:
        mid = (lo + hi) // 2
        bouquets = 0
        flowers = 0
        for day in bloomDay:
            if day <= mid:
                flowers += 1
                if flowers == k:
                    bouquets += 1
                    flowers = 0
            else:
                flowers = 0
        if bouquets >= m:
            ans = mid
            hi = mid - 1
        else:
            lo = mid + 1
    return ans

